-- Payment facts are stored once per payment device. Other datasets keep their original scopes.
CREATE VIEW IF NOT EXISTS pollo_da_fact_rows_read AS SELECT * FROM pollo_da_fact_rows WHERE dataset<>'pay_type' OR platform='all' UNION ALL SELECT "dataset","source_record_id","period","week_start","week_end",CASE WHEN device_type='web' THEN 'web' ELSE 'app' END AS platform,"device_type","platform_type","dataset_kind","analysis_level","pay_type","function_name","user_tag","creation_cnt_30d_level_id","creation_cnt_30d","plan_tier","plan_cycle","active_uv","creation_uv","creation_task_cnt","creation_penetration_rate","avg_creation_task_cnt_per_creator","sub_expose_uv","sub_submit_uv","chain_pay_uv","chain_gmv_usd","sub_expose_rate","sub_submit_rate","chain_pay_success_rate","chain_arppu","expire_user_cnt","renew_user_cnt","renew_amount_usd","pay_user_cnt","order_cnt","gmv_usd","fields_json","updated_at","subscription_tier","attribution_type","attribution_name","actual_supplier","actual_provider","pay_category","order_equivalent","model_cost_usd","metric_version","product_type","product_type_lv2" FROM pollo_da_fact_rows WHERE dataset='pay_type' AND platform='all' AND device_type IN ('web','ios','android');
